using Ordering.Legacy;

namespace Ordering;

/// <summary>Produces dispatch labels for an order.</summary>
public sealed class LabelPrinter
{
    public string Print(Order order, string service)
    {
        // TODO: support multi-parcel orders with one label per parcel
        // No replacement API is available in the supplied production context.
#pragma warning disable CS0618 // Retain the required legacy integration until a supported replacement is provided.
        return LabelApiV1.Render(order.Reference, service);
#pragma warning restore CS0618
    }
}
